CREATE TABLE schema_versions(version integer PRIMARY KEY, installed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY, username text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','operator','approver')), active boolean NOT NULL DEFAULT true);
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, expires_at timestamptz NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE rate_limits(key text NOT NULL, bucket bigint NOT NULL, hits integer NOT NULL, PRIMARY KEY(key,bucket));
CREATE TABLE suppliers(id uuid PRIMARY KEY, name text UNIQUE NOT NULL);
CREATE TABLE purchase_orders(id uuid PRIMARY KEY, reference text UNIQUE NOT NULL, supplier_id uuid NOT NULL REFERENCES suppliers, currency text NOT NULL CHECK(currency IN ('PKR','USD','EUR','GBP')));
CREATE TABLE po_lines(id uuid PRIMARY KEY, po_id uuid NOT NULL REFERENCES purchase_orders, description text NOT NULL, quantity numeric(14,3) NOT NULL CHECK(quantity>0), unit_price numeric(14,4) NOT NULL CHECK(unit_price>=0));
CREATE TABLE invoices(id uuid PRIMARY KEY, sha256 text UNIQUE NOT NULL, media_type text NOT NULL, page_count integer NOT NULL CHECK(page_count BETWEEN 1 AND 10), uploader_id uuid NOT NULL REFERENCES users, reviewer_id uuid REFERENCES users, state text NOT NULL DEFAULT 'needs_review' CHECK(state IN ('needs_review','submitted','approved','rejected','exported')), version integer NOT NULL DEFAULT 0, review jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX invoices_queue ON invoices(created_at DESC);
CREATE TABLE invoice_numbers(supplier_id uuid NOT NULL REFERENCES suppliers, number text NOT NULL, invoice_id uuid UNIQUE NOT NULL REFERENCES invoices, PRIMARY KEY(supplier_id,number));
CREATE TABLE invoice_versions(invoice_id uuid NOT NULL REFERENCES invoices, version integer NOT NULL, actor_id uuid NOT NULL REFERENCES users, review jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(invoice_id,version));
CREATE TABLE jobs(id uuid PRIMARY KEY, invoice_id uuid UNIQUE NOT NULL REFERENCES invoices, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','done','failed')), attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), lease_token uuid, lease_until timestamptz, error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_claim ON jobs(status, available_at);
CREATE TABLE extraction_attempts(id uuid PRIMARY KEY, job_id uuid NOT NULL REFERENCES jobs, suggestion jsonb, error text, model text, elapsed_ms integer, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE allocations(invoice_id uuid NOT NULL REFERENCES invoices, line_index integer NOT NULL, po_line_id uuid NOT NULL REFERENCES po_lines, quantity numeric(14,3) NOT NULL CHECK(quantity>0), PRIMARY KEY(invoice_id,line_index));
CREATE INDEX allocations_po ON allocations(po_line_id);
CREATE TABLE audit_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id uuid REFERENCES users, action text NOT NULL, entity_id uuid, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE exports(id uuid PRIMARY KEY, invoice_id uuid UNIQUE NOT NULL REFERENCES invoices, csv text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
